selector_to_html = {"a[href=\"grpo-baseline.html#what-the-baseline-validates\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">What the Baseline Validates<a class=\"headerlink\" href=\"#what-the-baseline-validates\" title=\"Link to this heading\">#</a></h2>", "a[href=\"platforms.html#adding-a-new-platform\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Adding a New Platform<a class=\"headerlink\" href=\"#adding-a-new-platform\" title=\"Link to this heading\">#</a></h2><p>Vendors can add a new hardware platform by:</p>", "a[href=\"#user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>This section provides guidance on running verl RL post-training workloads across hardware platforms with verl-hardware-plugin.</p>", "a[href=\"platforms.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Platform Guide<a class=\"headerlink\" href=\"#platform-guide\" title=\"Link to this heading\">#</a></h1><p>This page summarizes the hardware platforms verl-hardware-plugin ships implementations for. For complete, up-to-date installation and quick-start steps, use the platform guide in the repository (linked for each platform).</p>", "a[href=\"grpo-baseline.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">GRPO Acceptance Baseline (GSM8K)<a class=\"headerlink\" href=\"#grpo-acceptance-baseline-gsm8k\" title=\"Link to this heading\">#</a></h1><p>The standard acceptance test for a new hardware platform adaptation is GRPO training on GSM8K with Qwen3-0.6B. The reference implementation is <code class=\"docutils literal notranslate\"><span class=\"pre\">scripts/baseline_grpo_gsm8k.sh</span></code> in the repository.</p>", "a[href=\"grpo-baseline.html#flagos-engine-environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">FlagOS Engine Environment Variables<a class=\"headerlink\" href=\"#flagos-engine-environment-variables\" title=\"Link to this heading\">#</a></h2><p>When running with the FlagOS engine (vendor <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code>), the following variables control stage-scoped acceleration:</p>", "a[href=\"grpo-baseline.html#running-the-baseline\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Running the Baseline<a class=\"headerlink\" href=\"#running-the-baseline\" title=\"Link to this heading\">#</a></h2><p>The script uses these default hyperparameters (all overridable via environment variables):</p>", "a[href=\"platforms.html#platform-specific-notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Platform-Specific Notes<a class=\"headerlink\" href=\"#platform-specific-notes\" title=\"Link to this heading\">#</a></h2><h3>NVIDIA (FlagOS engine)<a class=\"headerlink\" href=\"#nvidia-flagos-engine\" title=\"Link to this heading\">#</a></h3><p>The FlagOS engine registers as an engine vendor (<code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code>) on top of the <code class=\"docutils literal notranslate\"><span class=\"pre\">cuda</span></code> device platform, rather than as a standalone platform.</p>", "a[href=\"platforms.html#platform-summary\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Platform Summary<a class=\"headerlink\" href=\"#platform-summary\" title=\"Link to this heading\">#</a></h2><p>For CUDA-compatible devices (MetaX, Iluvatar, NVIDIA), <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda.is_available()</span></code> returns True on all of them. The platform layer uses <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor_name</span></code> and SMI-based detection (<code class=\"docutils literal notranslate\"><span class=\"pre\">mx-smi</span></code> for MetaX, <code class=\"docutils literal notranslate\"><span class=\"pre\">nvidia-smi</span></code> for NVIDIA) at first auto-detection to select the correct engine.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
